def image(s):
    return f'<img src="assets/{s["image"]}.{"svg" if s["image"]=="floorplan" else "webp"}" alt="{e(s["title"])} — illustrative fictional concept">'
def contents(s):
    head=f'<div class="eyebrow">{e(s["subtitle"])}</div><h1>{e(s["title"])}</h1>'
    desc=f'<p>{e(s["body"])}</p>'
    points='<ul>'+''.join(f'<li>{e(x)}</li>' for x in s['points'])+'</ul>' if s['points'] else ''
    kind=s['kind']
    if kind in ['cover','hero']:
        return image(s)+f'<div class="overlay">{head}{desc}</div>'
    if kind=='board': return f'<div class="inner"><div>{head}{desc}</div>{image(s)}</div>'
    if s['image']: return f'<div class="split"><div class="copy">{head}{desc}{points}</div>{image(s)}</div>'
    extra=''
    if kind=='palette':
        extra='<div class="swatches">'+''.join(f'<div class="swatch" style="background:{c}">{n}<small>{c.upper()}</small></div>' for c,n in zip(manifest['theme']['colors'],['Chalk','Sand oak','Mushroom','Olive','Bronze']))+'</div>'
    if kind=='budget':
        lines=[r for r in budget if not r['included'] and not r['optional'] and r['kind']!='unknown']
        extra='<table><thead><tr><th>Package</th><th>Basis</th><th>Investment incl. assumed VAT</th></tr></thead><tbody>'+''.join(f'<tr><td>{e(r["label"])}</td><td>{"Allowance" if r["kind"]=="estimate" else "Fictional quote"}</td><td>{money(r["amount"]) if r["amount"] is not None else money(r["min_amount"])+"–"+money(r["max_amount"])}</td></tr>' for r in lines)+'</tbody></table><div class="total"><span>Known project range</span><span>€278,500–€286,500</span></div>'
    if kind=='hierarchy':
        extra='<div class="tree"><article><h3>Forma Build · €82,000</h3><div>Own work · €28,500</div><div class="child">Lumen Works · €18,500 <small>included</small><div class="child">Signal Atelier · €4,800 included<br>Electrical own work · €13,700</div></div><div class="child">Flow Systems · €14,000 included</div><div class="child">Terra Surface · €21,000 included</div></article><article><h3>Grain Atelier · €54,000</h3><div>Cabinetry & fitting · €26,000</div><div class="child">Quarry Objects · €16,000 included</div><div class="child">Quiet Appliances · €12,000 included</div><br><div>+ Optional study · €9,600</div><small>Additional to parent; unselected by default.</small></article></div>'
    if kind=='options':
        extra='<div class="cards">'+''.join(f'<article class="card"><h3>{title}</h3><strong>{price}</strong><p>{text}</p></article>' for title,price,text in [('Furniture upgrade','+ €8,000','Premium textile and rug selection. The furniture range moves from €36,000 to €44,000.'),('Bespoke study','+ €9,600','Optional additional joinery package. The study visual includes this upgrade.'),('Terrace living','+ €18,500','Optional loose outdoor furniture and pots. Landscaping remains unpriced.')])+'</div>'
    if kind=='timeline':
        extra='<div class="timeline">'+''.join(f'<article><small>{e(timing)}</small><h3>{e(phase)}</h3><p>{e(deliverable)}</p></article>' for _,timing,phase,deliverable in schedule)+'</div>'
    if s['points']:extra+='<div class="bigpoints">'+''.join(f'<div><span>{i:02d}</span>{e(x)}</div>' for i,x in enumerate(s['points'],1))+'</div>'
    return f'<div class="inner">{head}{desc}{extra}</div>'

deck=''.join(f'<section class="slide {s["kind"]}" id="{s["key"]}" aria-label="Slide {i}: {e(s["title"])}">{contents(s)}<footer class="folio"><span>AUREN / INTERIOR STUDIO</span><span>FICTIONAL DEMO · AI CONCEPT IMAGERY</span><span>{i:02d} / {len(slides):02d}</span></footer></section>' for i,s in enumerate(slides,1))
script='''<script>const slides=[...document.querySelectorAll('.slide')];let current=0;const observer=new IntersectionObserver(entries=>{for(const x of entries)if(x.isIntersecting){current=slides.indexOf(x.target);document.querySelector('#counter').textContent=`${current+1} / ${slides.length}`;}},{threshold:.55});slides.forEach(x=>observer.observe(x));function move(n){current=Math.max(0,Math.min(slides.length-1,current+n));slides[current].scrollIntoView({behavior:'smooth'});}document.querySelector('#prev').onclick=()=>move(-1);document.querySelector('#next').onclick=()=>move(1);document.querySelector('#full').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();document.addEventListener('keydown',e=>{if(['ArrowRight','PageDown','ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();move(['ArrowRight','PageDown'].includes(e.key)?1:-1);}});function scale(){document.documentElement.style.setProperty('--scale',Math.min(1,innerWidth/1280))}scale();addEventListener('resize',scale);</script>'''
(OUT/'index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Villa Auren — Interior concept</title><style>'+CSS+'</style><body>'+deck+'<nav class="toolbar" aria-label="Presentation controls"><button id="prev" aria-label="Previous slide">←</button><span id="counter">1 / 25</span><button id="next" aria-label="Next slide">→</button><button id="full">Fullscreen</button><a href="Villa-Auren-Presentation.pdf">PDF</a><a href="supplier-index.html">Supplier pack</a></nav>'+script+'</body></html>')

DOC_CSS='''@page{size:A4;margin:16mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#32372e;max-width:760px;margin:40px auto;font-size:12px;line-height:1.35}h1,h2{font-family:Georgia,serif;font-weight:400}h1{font-size:32px;margin-bottom:4px}h2{font-size:18px;margin-top:14px;break-after:avoid}.tag{font-size:10px;letter-spacing:2px;text-transform:uppercase;color:#717963}.banner{border:1px solid #909581;padding:10px 14px;background:#f1f0e8;margin:14px 0}.meta{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:12px 0}table{width:100%;border-collapse:collapse;font-size:12px}td,th{padding:8px 8px;border-bottom:1px solid #d6d9cf;text-align:left}td:last-child{text-align:right;white-space:nowrap}.total{font-size:22px;display:flex;justify-content:space-between;padding:15px;background:#e5e8dd}footer{margin-top:12px;border-top:1px solid #ccc;padding-top:12px;color:#6d7464;font-size:10px}a{color:#46593e}@media print{body{margin:0}.noprint{display:none}}'''
def document(title,body):return f'<!doctype html><html lang="en"><meta charset="utf-8"><title>{e(title)}</title><style>{DOC_CSS}</style><body>{body}</body></html>'
for ref,vendor,role,key,lines,lead,exclusions in quotes:
    gross=sum(x[1] for x in lines);net=round(gross/1.21,2);tax=round(gross-net,2)
    b=next(r for r in budget if r['key']==key)
    body=f'<div class="tag">{e(role)} / Fictional supplier</div><h1>{e(vendor)}</h1><p>{vendor.lower().replace(" ",".")}@example.test</p><div class="banner"><strong>FICTIONAL DEMO QUOTATION — NOT A VALID COMMERCIAL OFFER</strong><br>Created for the StudioDeck Villa Auren demonstration. No supplier has issued this document.</div><div class="meta"><div><strong>Prepared for</strong><br>Eva & Julian Vermeer (fictional)<br>Villa Auren · Bergen, Netherlands<br>Via Auren Interior Studio (fictional)</div><div><strong>Reference</strong> {ref}<br><strong>Issued</strong> 18 September 2026<br><strong>Illustrative validity</strong> 30 days<br><strong>Currency</strong> EUR</div></div><h2>{e(b["label"])}</h2><table><thead><tr><th>Scope / package</th><th>Amount incl. assumed VAT</th></tr></thead><tbody>'+''.join(f'<tr><td>{e(label)}</td><td>{money(value)}</td></tr>' for label,value in lines)+f'</tbody></table><div class="total"><span>{"Base allowance" if key=="furniture" else "Package total"}</span><strong>{money(gross)}</strong></div><p>Illustrative net €{net:,.2f} + assumed 21% VAT €{tax:,.2f} = €{gross:,.2f}. A uniform VAT assumption is used solely for demo arithmetic.</p><h2>Scope relationship</h2><p>{e(b["note"])}</p><h2>Programme & commercial assumptions</h2><p>{e(lead)} Payment example: 40% on order, 40% before delivery, 20% after agreed handover. No payments are requested by this demo. Final quantities and technical suitability are subject to site survey.</p><h2>Exclusions & qualifications</h2><p>{e(exclusions)}</p><footer>VILLA AUREN / {ref} / Fictional names and figures. No signature, registration number or bank details are supplied. Do not use for purchasing or construction.</footer>'
    (OUT/'suppliers'/f'{ref}.html').write_text(document(ref+' — '+vendor,body))

scope='''<div class="tag">Villa Auren / Demo scope schedule / 18 September 2026</div><h1>The scope, in plain language.</h1><div class="banner">FICTIONAL DEMO DOCUMENT · Illustrative project assumptions, not a contract.</div><h2>Included in the known investment</h2><p>Interior construction and installation; kitchen and oak joinery; furniture allowance; decorative lighting; curtains; primary bathroom fixtures; art and styling; design coordination; and a €25,000 client-held contingency. Base €278,500; premium furniture selection €286,500. Amounts use a fictional VAT-inclusive basis.</p><h2>How subcontractors are counted</h2><p>Forma Build €82,000 includes Lumen Works €18,500, Flow Systems €14,000 and Terra Surface €21,000. Lumen Works includes Signal Atelier €4,800. Grain Atelier €54,000 includes Quarry Objects €16,000 and Quiet Appliances €12,000. These included amounts are not added again. The optional study library €9,600 is additional to Grain Atelier.</p><h2>Options and unpriced work</h2><p>Study library €9,600 and terrace furniture €18,500 are not selected in the base total. Premium furniture adds €8,000. All selections together total €314,600. Landscape design and external works are unknown, not zero, and excluded from every stated total.</p><h2>Boundaries between packages</h2><p>Electrical installation and controls are within construction; decorative light fittings are in Halo Objects. Rough-in plumbing is within construction; sanitary fixtures and their installation are in Still Bath. Kitchen worktops are in Quarry Objects; general stone floors are in Terra Surface. The €25,000 contingency is a separate client reserve and is not charged by a supplier.</p><h2>Not included</h2><p>Land or property purchase, new-build shell, structural alterations, roof and external glazing, permits, structural engineering, asbestos remediation, boiler replacement, landscaping, external construction, unlisted rooms and unapproved variations. Generated images may show illustrative architectural elements beyond the priced interior scope.</p><h2>Approvals and changes</h2><p>Review the site survey, final dimensions, material samples, technical details and complete supplier scopes before a real commission. Record any change in writing and revise the relevant budget line. The 24-week programme is illustrative. No client approval, purchase order, payment, supplier acceptance or construction instruction is represented by this pack.</p><footer>All clients and vendors are fictional. All imagery is AI-generated concept imagery. The schematic plan is not measured and is not suitable for construction.</footer>'''
(OUT/'scope.html').write_text(document('Villa Auren — Scope & assumptions',scope))
index='<div class="tag">Villa Auren / Procurement library</div><h1>Every detail, together.</h1><div class="banner">All 15 supplier documents are fictional. Included subquotes remain inside their parent totals.</div><p><a href="index.html">Open presentation</a> · <a href="Villa-Auren-Presentation.pdf">Presentation PDF</a> · <a href="budget.csv">Budget CSV</a> · <a href="materials.csv">Material schedule</a> · <a href="programme.csv">Programme</a> · <a href="scope.pdf">Scope PDF</a></p><table><tr><th>Reference / download</th><th>Supplier</th><th>Relationship</th></tr>'
